    rows = []
    for line in text.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        # Assuming CSV format: prompt_id, tok_s, correction_tokens
        parts = line.split(',')
        if len(parts) != 3:
            continue
        try:
            prompt_id = parts[0].strip()
            tok_s = float(parts[1].strip())
            correction_tokens = int(parts[2].strip())
